import { Pipe, PipeTransform } from '@angular/core';
import { Credito } from '../models/credito.model';

@Pipe({
  name: 'estadocomprobacion',
  standalone: true
})
export class EstadoComprobacionPipe implements PipeTransform {

  transform(value?: Credito, ...args: unknown[]): unknown {
    if(!value) return;
    const comprobaciones = value.credito_comprobaciones
    const comprobacion_total_s2c = value.comprobacion_total_s2c
        
    if(this.isReestructurado(value) && comprobacion_total_s2c?.credito_comprobaciones){
      const todas = [...comprobaciones??[], ...comprobacion_total_s2c.credito_comprobaciones]
      const total = todas.reduce((acc, item) => acc + +item.monto, 0)
      if(total>= comprobacion_total_s2c.capital){
        return "SI - por comprobar $0.00";
      }
      return 'NO - por comprobar ' + this.formatCurrency((comprobacion_total_s2c.capital) - total);
      //return 'Este crédito proviene de una reestructura y el monto original por comprobar es: ' + this.formatCurrency(comprobacion_total_s2c.capital ?? 0);
    }
    if (!comprobaciones) return 'NO - por comprobar ' + this.formatCurrency(value.monto_autorizado ?? 0);
    const total = comprobaciones.reduce((acc, item) => acc + +item.monto, 0) + 0.0005
    if (total >= (value.monto_autorizado ?? 0)) return 'SI -  por comprobar $0.00';
    return 'NO - por comprobar ' + this.formatCurrency((value.monto_autorizado ?? 0) - total);
  }

  private isReestructurado(credito:Credito){
    const lastLetter = credito.folio?.slice(-1).toUpperCase();
    const hasActiveConvenios = !!credito.convenios?.some(conv => conv.estatus === 'ACTIVO');
    
    return lastLetter === 'R' || hasActiveConvenios;
  }

  /**
 * Formatea un número como moneda con opciones configurables
 * @param value Valor numérico a formatear
 * @param options Opciones de formato (opcional)
 * @returns Cadena formateada como moneda
 * 
 * Ejemplos:
 * formatCurrency(1234567.89) → "$1,234,567.89"
 * formatCurrency(1234567.89, { currency: 'EUR', locale: 'de-DE' }) → "1.234.567,89 €"
 */
  formatCurrency(
    value: number | string,
    options: {
      currency?: string;
      locale?: string;
      minimumFractionDigits?: number;
      maximumFractionDigits?: number;
    } = {}
  ): string {
    // Configuración por defecto (USD)
    const {
      currency = 'USD',
      locale = 'en-US',
      minimumFractionDigits = 2,
      maximumFractionDigits = 2
    } = options;

    // Convertir a número si es string
    const numericValue = typeof value === 'string' ? parseFloat(value) : value;

    // Validar que sea un número válido
    if (isNaN(numericValue)) {
      console.warn('Valor no numérico proporcionado a formatCurrency');
      return 'NaN';
    }

    // Formatear como moneda
    return new Intl.NumberFormat(locale, {
      style: 'currency',
      currency,
      minimumFractionDigits,
      maximumFractionDigits
    }).format(numericValue);
  }
}
