import { Component, Input, SimpleChanges } from '@angular/core';
import { Credito } from '../../../../models/credito.model';
import { CurrencyPipe, DatePipe } from '@angular/common';
import { UtilsService } from '../../../../services/utils.service';
import { EstadoCuenta, UtilsEstadoCuentaService } from '../../services/utils-estado-cuenta.service';
import { CollapsableComponent } from "../../../../shared/collapsable/collapsable.component";
import { EstadoComprobacionPipe } from '../../../../pipes/estado-comprobacion.pipe';
import { CreditoService } from '../../../../controllers/credito.service';

@Component({
  selector: 'app-view-resumen-credito',
  imports: [
    CurrencyPipe,
    DatePipe,
    CollapsableComponent,
    EstadoComprobacionPipe
  ],
  templateUrl: './view-resumen-credito.component.html',
  styleUrl: './view-resumen-credito.component.css'
})
export class ViewResumenCreditoComponent {
  @Input() credito!: Credito
  @Input() title = 'Datos del Crédito'
  @Input() useLocal?: boolean
  estadoCuenta?: EstadoCuenta
  origenCredito: string = ''
  esReestructura: boolean = false

  creditoOriginal?: Credito
  acreditado: string = '';

  constructor(
    public utils: UtilsService,
    private utilsEstadoCuenta: UtilsEstadoCuentaService,
    private creditoController: CreditoService,
  ) { }

  ngOnChanges(changes: SimpleChanges) {
    if (changes['credito']) {
      this.setData()
      this.setIsReestructurado()
      this.checkIfIsReestructura()
    }
  }

  private async checkIfIsReestructura() {
    if (this.credito.folio) {
      const folioOriginal = this.utils.folioOriginalFromCredito(this.credito)
      this.creditoOriginal = await this.creditoController.first({ folio: folioOriginal, deleted_at: null }, ['*'], {}, false)
      this.acreditado = this.utils.nombreClienteFromCredito(this.creditoOriginal);

      console.log('acreditado:', this.acreditado);

      this.credito.credito_comprobaciones = this.creditoOriginal?.credito_comprobaciones
    }
  }


  private setIsReestructurado() {
    const lastLetter = this.credito.folio?.slice(-1).toUpperCase();

    this.esReestructura = lastLetter === 'R';
  }

  setData() {
    if (this.useLocal) {
      this.estadoCuenta = this.credito.estado_cuenta
    } else {
      this.estadoCuenta = this.utilsEstadoCuenta.getEstadoCuenta(this.credito)
    }
    this.setOrigen()
  }

  private setOrigen() {
    this.origenCredito = 'NUEVO CREDITO'
    if (this.credito.folio && this.credito.folio[this.credito.folio.length - 1] == 'R') {
      this.origenCredito = 'REESTRUCTURA'
    }
    if (this.credito.convenios?.some(conv => conv.estatus == 'ACTIVO')) {
      this.origenCredito = 'REESTRUCTURA' 
    }
    if(this.credito.convenios?.some(conv => conv.tipo_convenio == 'PAGO')){
      this.origenCredito = 'CONVENIO DE PAGO'
    }

  }
}
